# SPDX-License-Identifier: GPL-3.0-or-later

set -euo pipefail
project_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"; root="$(mktemp -d /tmp/devario-promotion-acceptance-test.XXXXXX)"; trap 'rm -rf -- "$root"' EXIT
mkdir "$root/bin" "$root/results"; printf 'candidate iso\n' > "$root/devario.iso"; printf 'installed disk\n' > "$root/installed.raw"; printf 'firmware\n' > "$root/OVMF_CODE.fd"
iso_sha="$(sha256sum "$root/devario.iso" | cut -d' ' -f1)"; iso_size="$(stat -c '%s' "$root/devario.iso")"; iso_mode="$(stat -c '%a' "$root/devario.iso")"
jq -n --arg sha "$iso_sha" --argjson size "$iso_size" --arg mode "$iso_mode" '{schemaVersion:2,edition:"community",version:"test",architecture:"x86_64",candidateChannel:"devario-core-testing",coreCommit:("a"*40),overlayCommit:null,sourceDateEpoch:1786579200,createdAt:"2026-08-13T00:00:00Z",artifacts:[{path:"devario.iso",sha256:$sha,size:$size,mode:$mode}],artifactSetSha256:("a"*64),metadata:[{path:"release.json",sha256:("b"*64),size:1,mode:"644"}],metadataSetSha256:("c"*64),buildEvidence:{coreInputLock:{name:"CORE-INPUT-LOCK.json",sha256:("d"*64)},overlayInputLock:null,builderManifest:{name:"CONTROLLED-BUILDER.json",sha256:("1"*64)},builderManifestSignature:{name:"CONTROLLED-BUILDER.json.sig",sha256:("2"*64)},builderAttestation:{name:"BUILDER-ATTESTATION.json",sha256:("e"*64)},builderAttestationSignature:{name:"BUILDER-ATTESTATION.json.sig",sha256:("3"*64)}}}' > "$root/candidate.json"
printf '%s\n' '#!/usr/bin/env bash' 'request=' 'for argument in "$@"; do case "$argument" in name=opt/org.devario/acceptance,string=*) request="${argument#*string=}";; esac; done' 'printf "DEVARIO_ACCEPTANCE:PASS %s\n" "$request"' > "$root/bin/qemu-system-x86_64"; chmod 0755 "$root/bin/qemu-system-x86_64"
DEVARIO_INSTALLATION_LOCK_TIME=2026-08-13T00:00:00Z "$project_dir/release/generate-installation-lock.sh" --candidate "$root/candidate.json" --source-image "$root/devario.iso" --disk "$root/installed.raw" --disk-format raw --output "$root/installation-lock.json" >/dev/null
for mode in live installed; do for firmware in bios uefi; do
  [[ "$mode:$firmware" != installed:bios ]] || continue
  prefix="$root/results/$mode-$firmware"; args=(--candidate "$root/candidate.json" --mode "$mode" --firmware "$firmware" --edition community --log "$prefix.log" --result "$prefix.json" --timeout 5)
  if [[ "$mode" == live ]]; then args+=(--image "$root/devario.iso"); else args+=(--disk "$root/installed.raw" --disk-format raw --source-image "$root/devario.iso" --installation-lock "$root/installation-lock.json"); fi
  PATH="$root/bin:$PATH" DEVARIO_OVMF_CODE="$root/OVMF_CODE.fd" "$project_dir/scripts/test-image-boot.sh" "${args[@]}" >/dev/null
done; done
fingerprint=1111111111111111111111111111111111111111
jq -n --arg candidate "$(sha256sum "$root/candidate.json" | cut -d' ' -f1)" --arg lock "$(sha256sum "$root/installation-lock.json" | cut -d' ' -f1)" --arg disk "$(sha256sum "$root/installed.raw" | cut -d' ' -f1)" --arg fingerprint "$fingerprint" '{schemaVersion:1,candidateSha256:$candidate,candidateVersion:"test",installationLockSha256:$lock,installedDiskSha256:$disk,edition:"community",installer:"calamares",reviewer:"ZoeyErinBauer",reviewerFingerprint:$fingerprint,reviewedAt:"2026-08-13T01:00:00Z",checks:{graphicalLaunch:true,targetSelection:true,partitionSummary:true,bootloaderChoice:true,completionScreen:true,noSecretsCaptured:true},decision:"pass"}' > "$root/installation-review.json"
printf 'detached signature fixture\n' > "$root/installation-review.json.sig"
jq -n --arg fingerprint "$fingerprint" '{"$schema":"./trust-policy.schema.json",schemaVersion:1,purpose:"human-release-approval",activeFingerprint:$fingerprint,approvedFingerprints:[$fingerprint],forbiddenFingerprints:["580E40BB6D6E8745D69D89CC6E6C90512593874C","E199A52D6C3B80057E08C7BB645354F2E56FEC5D"]}' > "$root/trust.json"; printf 'public key fixture\n' > "$root/approvers.gpg"
printf '%s\n' '#!/usr/bin/env bash' 'printf "[GNUPG:] VALIDSIG 1111111111111111111111111111111111111111 2026-08-13 1786579200 0 4 0 22 8 00 1111111111111111111111111111111111111111\n"' > "$root/bin/gpgv"; chmod 0755 "$root/bin/gpgv"
printf '%s\n' '#!/usr/bin/env bash' 'printf "pub:::::::::\nfpr:::::::::1111111111111111111111111111111111111111:\n"' > "$root/bin/gpg"; chmod 0755 "$root/bin/gpg"
"$project_dir/release/generate-promotion-acceptance.sh" --candidate "$root/candidate.json" --installed-disk "$root/installed.raw" --disk-format raw --installation-lock "$root/installation-lock.json" --installation-review "$root/installation-review.json" --review-signature "$root/installation-review.json.sig" --live-bios-result "$root/results/live-bios.json" --live-bios-log "$root/results/live-bios.log" --live-uefi-result "$root/results/live-uefi.json" --live-uefi-log "$root/results/live-uefi.log" --installed-uefi-result "$root/results/installed-uefi.json" --installed-uefi-log "$root/results/installed-uefi.log" --output "$root/evidence" >/dev/null
PATH="$root/bin:$PATH" "$project_dir/release/validate-promotion-acceptance.sh" --manifest "$root/evidence/promotion-acceptance.json" --evidence-dir "$root/evidence" --candidate "$root/candidate.json" --source-image "$root/devario.iso" --trust-policy "$root/trust.json" --keyring "$root/approvers.gpg" >/dev/null
printf 'unrelated iso\n' > "$root/unrelated.iso"
if PATH="$root/bin:$PATH" "$project_dir/release/validate-promotion-acceptance.sh" --manifest "$root/evidence/promotion-acceptance.json" --evidence-dir "$root/evidence" --candidate "$root/candidate.json" --source-image "$root/unrelated.iso" --trust-policy "$root/trust.json" --keyring "$root/approvers.gpg" >/dev/null 2>&1; then echo 'Promotion acceptance allowed an image outside the candidate.' >&2; exit 1; fi
printf 'extra\n' > "$root/evidence/undeclared.txt"
if PATH="$root/bin:$PATH" "$project_dir/release/validate-promotion-acceptance.sh" --manifest "$root/evidence/promotion-acceptance.json" --evidence-dir "$root/evidence" --candidate "$root/candidate.json" --source-image "$root/devario.iso" --trust-policy "$root/trust.json" --keyring "$root/approvers.gpg" >/dev/null 2>&1; then echo 'Promotion acceptance allowed undeclared evidence.' >&2; exit 1; fi
echo 'Promotion acceptance tests passed.'
